{
  "statement": {
    "index": 1,
    "modal": "Must",
    "text": "judge-jev MUST ship one question set per combination of record kind and\ntarget class (agent text or code)."
  },
  "record": {
    "id": "REQ-JEV-0205",
    "title": "Question sets ship with the tool",
    "status": "Draft",
    "version": "0.1.0",
    "created": "2026-11-07",
    "last_updated": "2026-11-08",
    "owner": "Rand Lee",
    "supersedes": null,
    "superseded_by": null,
    "requirement_statement": {
      "text": "Definitions: A question set is the data file of questions judge-jev sends to\nJev for one record kind and target class. A quality decision tree is the\ndata file of questions that judges whether a record is well written. The\ncontent digest of a file is its SHA-256. An override file is a file that\nreplaces the shipped question set or quality decision tree. A log entry is\none event a run writes.",
      "statements": [
        {
          "modal": "Must",
          "text": "judge-jev MUST ship one question set per combination of record kind and\ntarget class (agent text or code)."
        },
        {
          "modal": "Must",
          "text": "judge-jev MUST ship one quality decision tree per record kind."
        },
        {
          "modal": "Must",
          "text": "Every shipped question and prompt text MUST be approved by Rand before\nit ships."
        },
        {
          "modal": "Must",
          "text": "Question sets MUST be data files shipped with the tool."
        },
        {
          "modal": "Must",
          "text": "Quality decision trees MUST be data files shipped with the tool."
        },
        {
          "modal": "Must",
          "text": "The released tool MUST accept, with `--questions <file>`, an override file\nfor any question set."
        },
        {
          "modal": "Must",
          "text": "The released tool MUST accept an override file for any quality decision\ntree."
        },
        {
          "modal": "Must",
          "text": "Every result MUST carry the question-set id."
        },
        {
          "modal": "Must",
          "text": "Every result MUST carry the content digest of the file used."
        },
        {
          "modal": "Must",
          "text": "Every log entry MUST carry the question-set id."
        },
        {
          "modal": "Must",
          "text": "Every log entry MUST carry the content digest of the file used."
        }
      ]
    },
    "rationale": "Rand: \"I do not trust non-frontier agents to write prompts. I do not even\ntrust frontier agents to write them.\" The question sets are the tool's\nsystem prompts. Getting them production-worthy means running thousands of\nquestion variations against the released tool; a variation that needs a\ncode change cannot be run at that scale.\n\nBecause question sets and trees are data files, changing a question, a\ntree branch or a wave needs no code change. An override file lets a\nvariation be tried by writing a file, never by changing or rebuilding code.\nThe question-set id and file digest on every result and log entry let\nresults from many variations of the same set be told apart and compared.",
    "success_criteria": {
      "text": "",
      "acceptance_criteria": [
        {
          "text": "Each shipped question file names the approval that admitted its text.",
          "checked": false
        },
        {
          "text": "A result produced with an override names the override file and its\ndigest.",
          "checked": false
        },
        {
          "text": "Two override files differing in one question produce results with\ndifferent digests, run on the same released build.",
          "checked": false
        },
        {
          "text": "Adding a wave to a quality tree changes only the tree file.",
          "checked": false
        }
      ],
      "test_evidence": []
    },
    "dependencies": {
      "text": "",
      "requires": [],
      "related": []
    },
    "product_applicability": {
