{
  "statement": {
    "index": 1,
    "modal": "Must",
    "text": "`judge-jev validate` MUST take one input file."
  },
  "record": {
    "id": "REQ-JEV-0210",
    "title": "Validate command",
    "status": "Draft",
    "version": "0.1.0",
    "created": "2026-11-07",
    "last_updated": "2026-11-08",
    "owner": "Rand Lee",
    "supersedes": null,
    "superseded_by": null,
    "requirement_statement": {
      "text": "Definitions: Jev is TypeSafe's hosted judge model: it answers each\nmultiple-choice question about a text with one choice and a confidence from\n0 to 1. A Jev request is one call to it. The model for an input kind is the\nPydantic model (a typed schema class) judge-jev validates that input with\n(ADR-JEV-0005). A field path is the dotted path of keys and list indexes to\nthe refused field, such as `nodes.wave-1.questions.context.criteria`. An\nanswers file is a JSON file of Jev's answers, keyed by request, that\n`--answers-file` gives judge-jev in place of a live call. Its envelope is\nits outer structure: its keys and the type of each value.\n`JEV.RESPONSE_INVALID` is the typed error code for an answer whose\nquestions, choices or probabilities do not match the request.",
      "statements": [
        {
          "modal": "Must",
          "text": "`judge-jev validate` MUST take one input file."
        },
        {
          "modal": "Must",
          "text": "`judge-jev validate` MUST take one input-kind flag with that file:\n`--tree` (quality tree), `--questions` (question set), `--answers`\n(answers file), `--index` (Raptor import index) or `--requests` (batch\nrequest stream)."
        },
        {
          "modal": "Must",
          "text": "`judge-jev validate` MUST check the file with the model `judge-jev`\napplies to that input kind before its first Jev request (ADR-JEV-0005)."
        },
        {
          "modal": "Must",
          "text": "Every refusal from `judge-jev validate` MUST name the field path."
        },
        {
          "modal": "Must",
          "text": "Every refusal from `judge-jev validate` MUST name the rule the field\nbreaks."
        },
        {
          "modal": "Must",
          "text": "`judge-jev validate --answers` MUST apply the answers-file envelope that\n`--answers-file` applies before the first request."
        },
        {
          "modal": "Must",
          "text": "The answers-file envelope MUST require an object of string keys."
        },
        {
          "modal": "Must",
          "text": "The answers-file envelope MUST require each key's value to be an object\nor a non-empty list of objects."
        },
        {
          "modal": "Must",
          "text": "The answers-file envelope MUST require an object with `__error__` to hold\nonly a string code of at most 64 characters."
        },
        {
          "modal": "MustNot",
          "text": "`judge-jev validate` MUST NOT call Jev."
        }
      ]
    },
    "rationale": "A tree variation checked before a run costs nothing; one refused after a\npaid call wastes it.\n\nThe answers file stands in for Jev's response, so what an answer holds\n(its questions, choices and probabilities) is not part of the envelope; it\nis checked after the send as `JEV.RESPONSE_INVALID`.",
    "success_criteria": {
      "text": "",
      "acceptance_criteria": [
        {
          "text": "Every input the sweep tests refuse in `quality` is refused by\n`judge-jev validate` with the same field path.",
          "checked": false
        },
        {
          "text": "The shipped trees and question sets pass `judge-jev validate`.",
          "checked": false
        }
      ],
      "test_evidence": []
    },
